script:
(function () {
  'use strict';
  // Federal income tax is worked out twice for 2026, without and with your charitable gifts, and
  // the difference is the tax the gifts save.
  //   Taxable income = AGI - larger of (standard deduction + non-itemizer cash gift deduction) or
  //     itemized deductions - senior deduction (Schedule 1-A, taken by itemizers and non-itemizers).
  //   Tax: ordinary brackets with qualified dividends and long-term gains stacked on top at
  //     0/15/20% (Qualified Dividends and Capital Gain Tax Worksheet).
  //   Gifts, itemizers: AGI limits applied in the Pub. 526 order (cash to public charities up to
  //     60% of AGI; other non-cash gifts up to 50% of AGI minus cash gifts; appreciated property
  //     held over a year, at market value, up to the smaller of 30% of AGI or 50% of AGI minus the
  //     cash and non-cash gifts). The 0.5%-of-AGI floor then comes off the allowed gifts, taken
  //     first from appreciated property, then non-cash, then cash (IRC 170(b)(1)(I) ordering).
  //     Amounts over the AGI limits carry forward 5 years, and so does the part of the floor that
  //     falls on a category that went over its limit (IRC 170(d)(1)(C)).
  //   Itemized total (SALT after the cap, mortgage interest, other, gifts) is cut by 2/37 of the
  //     lesser of itemized deductions or income above the start of the 37% bracket (IRC 68), so
  //     a deduction saves at most 35 cents per dollar.
  //   Non-itemizers: up to $1,000 ($2,000 joint) of cash gifts to public charities, not donor-
  //     advised funds or supporting organizations (IRC 170(p)); the 0.5% floor does not apply.
  //   Capital gains tax avoided on donated appreciated property = gain x 0/15/20% rate at your
  //     taxable income (+3.8% NIIT when AGI is over the threshold). Not counted in tax savings.
  // Not modeled: credits, AMT, state tax, private foundation gifts (30%/20% limits), QBI.
  // Verified (Node scratch test, tests/cg.test.js, against hand calculations):
  //   Single, AGI $150,000, SALT $12,000, mortgage $8,000, $10,000 cash gift: floor $750,
  //     itemized $20,000 -> $29,250, taxable $130,000 -> $120,750, saving 9,250 x 24% = $2,220.00.
  //   Single, AGI $60,000, $1,500 cash gift, no itemized: $1,000 non-itemizer deduction,
  //     saving 1,000 x 12% = $120.00. Same gift to a donor-advised fund saves $0.
  //   Single, AGI $1,000,000, SALT $10,000 (cap phased down to the $10,000 floor), $100,000 cash:
  //     floor $5,000, itemized 105,000 - 2/37 x 105,000 = $99,324.32 vs $16,100 standard,
  //     saving 83,224.32 x 37% = $30,793.00 (35% of the $95,000 over the floor, less 37% of the
  //     standard deduction given up).
  //   AGI $100,000, $70,000 cash: allowed $60,000, floor $500, deductible $59,500, carryover
  //     $10,000 + $500 = $10,500.
  //   AGI $100,000, $40,000 appreciated stock: allowed $30,000, floor $500 on that category,
  //     carryover $10,500.
  //
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------
  // Brackets, standard deductions, additional 65+ amounts, capital gains breakpoints: IRS
  //   Rev. Proc. 2025-32 (as amended by P.L. 119-21) sections 4.01, 4.03, 4.14; same constants as
  //   income-tax-calculator.
  // Charity rules: P.L. 119-21 sec. 70424 (non-itemizer $1,000/$2,000, IRC 170(p)), sec. 70425
  //   (0.5% floor and carryforward, IRC 170(b)(1)(I), 170(d)(1)(C); 60% cash limit made
  //   permanent), sec. 70111 (2/37 itemized deduction limit, IRC 68); 2026 Form 1040-ES and
  //   Pub. 505 (2026). AGI limit order: Pub. 526 (2025), "How To Figure Your Deduction When
  //   Limits Apply".
  // SALT cap $40,400, cut by 30% of AGI over $505,000, floor $10,000 ($20,200 / $252,500 /
  //   $5,000 married filing separately): draft 2026 Schedule A, IRC 164(b)(7).
  // Senior deduction $6,000 per person 65+, less 6% of AGI over $75,000 ($150,000 joint):
  //   Schedule 1-A; not available married filing separately.
  // NIIT 3.8% thresholds: IRC 1411 (not indexed).
  var TAX_YEAR = 2026;
  var KEY = { single: 'single', mfj: 'mfj', mfs: 'mfs', hoh: 'hoh' };
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var CG_BREAKS = { single: [49450, 545500], mfj: [98900, 613700], hoh: [66200, 579600], mfs: [49450, 306850] };
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  var ADDITIONAL_STD = { single: 2050, hoh: 2050, mfj: 1650, mfs: 1650 }; // per person 65+
  var SALT_CAP = { single: 40400, mfj: 40400, hoh: 40400, mfs: 20200 };
  var SALT_PHASE = { single: 505000, mfj: 505000, hoh: 505000, mfs: 252500 };
  var SALT_FLOOR = { single: 10000, mfj: 10000, hoh: 10000, mfs: 5000 };
  var SENIOR_DEDUCTION = 6000, SENIOR_RATE = 0.06, SENIOR_PHASE = { mfj: 150000, other: 75000 };
  var NONITEMIZER_CHARITY = { mfj: 2000, other: 1000 };
  var CHARITY_FLOOR = 0.005;
  var LIMIT_CASH = 0.60, LIMIT_NONCASH = 0.50, LIMIT_PROPERTY = 0.30;
  var NIIT_RATE = 0.038, NIIT = { mfj: 250000, mfs: 125000, other: 200000 };
  // ---------------------------------------------------------------------------------------

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function pick(map, s) { return map[s] !== undefined ? map[s] : map.other; }

  function ordinaryTax(income, key) {
    var limits = BRACKETS[key], tax = 0, lower = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (income > lower) tax += (Math.min(income, upper) - lower) * RATES[i];
      lower = upper;
    }
    return tax;
  }
  function marginalRate(income, key) {
    var limits = BRACKETS[key];
    for (var i = 0; i < limits.length; i++) if (income <= limits[i]) return RATES[i];
    return RATES[RATES.length - 1];
  }
  function incomeTax(taxable, pref, key) {
    var gains = Math.max(0, Math.min(pref, taxable)), base = taxable - gains, b = CG_BREAKS[key];
    var mid = Math.max(0, Math.min(taxable, b[1]) - Math.max(base, b[0]));
    var top = Math.max(0, taxable - Math.max(base, b[1]));
    return Math.min(ordinaryTax(base, key) + 0.15 * mid + 0.20 * top, ordinaryTax(taxable, key));
  }
  function gainRate(taxable, key) {
    var b = CG_BREAKS[key];
    return taxable <= b[0] ? 0 : taxable <= b[1] ? 0.15 : 0.20;
  }

  // Applies AGI limits, then the 0.5% floor. g = { cash, daf, noncash, property }.
  function giftDeduction(g, agi) {
    var base = Math.max(0, agi);
    var cashOk = Math.min(g.cash, LIMIT_CASH * base);
    var noncashOk = Math.min(g.noncash, Math.max(0, LIMIT_NONCASH * base - g.cash));
    var propOk = Math.min(g.property, LIMIT_PROPERTY * base, Math.max(0, LIMIT_NONCASH * base - g.cash - g.noncash));
    var allowed = cashOk + noncashOk + propOk;
    var floor = Math.min(allowed, CHARITY_FLOOR * base);
    var left = floor;
    var fProp = Math.min(propOk, left); left -= fProp;
    var fNon = Math.min(noncashOk, left); left -= fNon;
    var fCash = Math.min(cashOk, left);
    var carry = (g.property - propOk + (g.property > propOk + 0.005 ? fProp : 0)) +
                (g.noncash - noncashOk + (g.noncash > noncashOk + 0.005 ? fNon : 0)) +
                (g.cash - cashOk + (g.cash > cashOk + 0.005 ? fCash : 0));
    return {
      rows: [
        { name: 'Cash to public charities', given: g.cash, limit: '60% of AGI', allowed: cashOk, floor: fCash },
        { name: 'Other non-cash items', given: g.noncash, limit: '50% of AGI', allowed: noncashOk, floor: fNon },
        { name: 'Appreciated property (held over 1 year)', given: g.property, limit: '30% of AGI', allowed: propOk, floor: fProp }
      ],
      allowed: allowed, floor: floor, deduction: allowed - floor, carry: carry
    };
  }

  function compute(o, g) {
    var s = o.status, key = KEY[s], agi = o.agi, joint = s === 'mfj';
    var seniors = (o.you65 ? 1 : 0) + (joint || s === 'mfs' ? (o.spouse65 ? 1 : 0) : 0);
    var standard = STANDARD_DEDUCTION[s] + seniors * ADDITIONAL_STD[s];
    var senior = 0;
    if (s !== 'mfs') {
      var seniorCount = (o.you65 ? 1 : 0) + (joint && o.spouse65 ? 1 : 0);
      senior = seniorCount * Math.max(0, SENIOR_DEDUCTION - SENIOR_RATE * Math.max(0, agi - pick(SENIOR_PHASE, s)));
    }
    var saltCap = Math.max(SALT_FLOOR[s], SALT_CAP[s] - 0.30 * Math.max(0, agi - SALT_PHASE[s]));
    var salt = Math.min(o.salt, saltCap);
    var gd = giftDeduction(g, agi);
    var itemizedRaw = salt + o.mortgage + o.otherItem + gd.deduction;
    var top = BRACKETS[key][BRACKETS[key].length - 1];
    var cut = (2 / 37) * Math.min(itemizedRaw, Math.max(0, agi - senior - top));
    var itemized = itemizedRaw - cut;
    var eligibleCash = Math.max(0, g.cash - g.daf);
    var nonItem = Math.min(eligibleCash, pick(NONITEMIZER_CHARITY, s), LIMIT_CASH * Math.max(0, agi));
    var itemize = itemized > standard + nonItem;
    var deduction = itemize ? itemized : standard + nonItem;
    var taxable = Math.max(0, agi - deduction - senior);
    var pref = Math.min(o.pref, Math.max(0, agi));
    return {
      standard: standard, nonItem: nonItem, itemized: itemized, cut: cut, itemize: itemize, deduction: deduction,
      senior: senior, taxable: taxable, tax: incomeTax(taxable, pref, key), gifts: gd,
      charityUsed: itemize ? gd.deduction : nonItem, marginal: marginalRate(Math.max(0, taxable - Math.min(pref, taxable)), key),
      key: key
    };
  }

  function num(id) {
    var el = document.getElementById(id);
    if (el.value === '') return 0;
    var v = parseFloat(el.value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function clearRows(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }
  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (t, i) {
      var td = document.createElement(i === 0 ? 'th' : 'td');
      if (i === 0) td.setAttribute('scope', 'row');
      td.textContent = t;
      tr.appendChild(td);
    });
    body.appendChild(tr);
  }

  function update() {
    var o = {
      status: document.getElementById('cgStatus').value, agi: num('cgAgi'), pref: num('cgPref'),
      salt: num('cgSalt'), mortgage: num('cgMortgage'), otherItem: num('cgOther'),
      you65: document.getElementById('cgYou65').checked, spouse65: document.getElementById('cgSpouse65').checked
    };
    var g = { cash: num('cgCash'), daf: num('cgDaf'), noncash: num('cgNoncash'), property: num('cgProperty') };
    var gain = num('cgGain');
    document.getElementById('cgSpouseWrap').hidden = !(o.status === 'mfj' || o.status === 'mfs');
    var error = document.getElementById('cgError');
    var vals = [o.agi, o.pref, o.salt, o.mortgage, o.otherItem, g.cash, g.daf, g.noncash, g.property, gain];
    var msg = '';
    if (vals.some(isNaN)) msg = 'Enter numbers only.';
    else if (vals.some(function (v) { return v < 0; })) msg = 'Amounts cannot be negative.';
    else if (g.daf > g.cash) msg = 'The donor-advised fund amount is part of your cash gifts, so it cannot be larger.';
    else if (gain > g.property) msg = 'The gain on donated property cannot be more than its market value.';
    error.hidden = !msg;
    error.textContent = msg;
    var ids = ['cgSavings', 'cgNetCost', 'cgPerDollar', 'cgCgAvoided', 'cgMethod', 'cgFloor', 'cgCut', 'cgCarry', 'cgMarginal'];
    if (msg) {
      ids.forEach(function (id) { set(id, '–'); });
      document.getElementById('cgNote').hidden = true;
      clearRows('cgCompare');
      clearRows('cgLimits');
      return;
    }
    if (!(o.status === 'mfj' || o.status === 'mfs')) o.spouse65 = false;
    var none = compute(o, { cash: 0, daf: 0, noncash: 0, property: 0 });
    var withG = compute(o, g);
    var total = g.cash + g.noncash + g.property;
    var savings = Math.max(0, none.tax - withG.tax);
    var niitOn = o.agi > pick(NIIT, o.status);
    var cgAvoided = gain * (gainRate(withG.taxable, withG.key) + (niitOn ? NIIT_RATE : 0));
    set('cgSavings', money.format(savings));
    set('cgNetCost', money.format(Math.max(0, total - savings - cgAvoided)));
    set('cgPerDollar', total > 0 ? (savings / total * 100).toFixed(1) + '¢' : '–');
    set('cgCgAvoided', money.format(cgAvoided));
    set('cgMethod', withG.itemize ? 'Itemize' : 'Standard deduction' + (withG.nonItem > 0 ? ' + gift deduction' : ''));
    set('cgFloor', withG.itemize ? money.format(withG.gifts.floor) : 'Does not apply');
    set('cgCut', money.format(withG.itemize ? withG.cut : 0));
    set('cgCarry', money.format(withG.itemize ? withG.gifts.carry : 0));
    set('cgMarginal', Math.round(withG.marginal * 100) + '%');

    var note = document.getElementById('cgNote');
    var text = '';
    if (total <= 0) text = 'Enter the gifts you plan to make to see what they save.';
    else if (!withG.itemize && withG.nonItem === 0 && g.cash > 0 && g.cash === g.daf)
      text = 'You take the standard deduction, and gifts to a donor-advised fund do not qualify for the $1,000/$2,000 deduction for non-itemizers, so these gifts save no federal income tax this year.';
    else if (!withG.itemize)
      text = 'You are better off with the standard deduction. Only cash gifts to public charities count, up to ' +
        whole.format(pick(NONITEMIZER_CHARITY, o.status)) + '. Bunching several years of gifts into one year can push you over the standard deduction.';
    else if (withG.cut > 0)
      text = 'Your income reaches the 37% bracket, so itemized deductions are trimmed by 2/37 and each deducted dollar saves about 35 cents, not 37.';
    else if (withG.gifts.carry > 0)
      text = 'Part of your gifts is over the AGI limits. You can carry ' + whole.format(withG.gifts.carry) + ' forward for up to five years.';
    else text = 'You itemize. The first ' + whole.format(withG.gifts.floor) + ' of your gifts (0.5% of AGI) is not deductible in ' + TAX_YEAR + '.';
    note.textContent = text;
    note.hidden = false;

    var body = clearRows('cgCompare');
    addRow(body, ['Deduction used', none.itemize ? 'Itemized' : 'Standard', withG.itemize ? 'Itemized' : 'Standard']);
    addRow(body, ['Charitable deduction', money.format(none.charityUsed), money.format(withG.charityUsed)]);
    addRow(body, ['Total deduction', money.format(none.deduction), money.format(withG.deduction)]);
    addRow(body, ['Senior deduction', money.format(none.senior), money.format(withG.senior)]);
    addRow(body, ['Taxable income', money.format(none.taxable), money.format(withG.taxable)]);
    addRow(body, ['Federal income tax', money.format(none.tax), money.format(withG.tax)]);
    addRow(body, ['Top tax bracket', Math.round(none.marginal * 100) + '%', Math.round(withG.marginal * 100) + '%']);

    var lim = clearRows('cgLimits');
    withG.gifts.rows.forEach(function (r) {
      addRow(lim, [r.name, money.format(r.given), r.limit, money.format(r.allowed), money.format(r.floor), money.format(r.allowed - r.floor)]);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('cgForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
